import{_ as t,c as r,o as a,a2 as n}from"./chunks/framework.PGES7OoM.js";const y=JSON.parse('{"title":"Curvy for networks","description":"","frontmatter":{"rawMarkdown":"# Curvy for networks\\n\\n> [!NOTE]\\n> If you are a blockchain ecosystem interested in partnering with Curvy, contact us at **<hey@curvy.box>**.\\n\\nCurvy provides native privacy infrastructure that can be integrated at the network level, enabling private, compliant, and programmable payment flows for your ecosystem participants.\\n\\nIn addition to default support for your network through the Curvy SDK and Curvy App, we offer deeper integration models tailored to your strategic goals.\\n\\n## Default Integration\\n\\nOut of the box, Curvy supports:\\n\\n- Private sending and receiving flows via the Curvy SDK  \\n- Network support within the Curvy App  \\n- Stealth address-based receiving  \\n- Privacy Aggregator support (where applicable)  \\n\\nThis allows your users, wallets, and applications to immediately benefit from privacy-enabled flows.\\n\\n## Custom Network-Level Integrations\\n\\n### White-label user domains\\n\\nLaunch your own ENS-style username namespace:\\n\\n`satoshi.yourdomain.io`  \\ninstead of  \\n`satoshi.curvy.name`\\n\\nThis allows your ecosystem to own the user-facing identity layer while leveraging Curvy’s underlying privacy infrastructure and customizing it to your needs.\\n\\n### Full protocol customization\\n\\nFor ecosystems seeking deeper integration, Curvy can be customized at the infrastructure level:\\n\\n- control over transaction routing paths\\n- selection of integrated DeFi protocols\\n- definition of supported tokens\\n- ecosystem-level fee configuration\\n- subsidized privacy flows\\n- incentive mechanisms for adoption\\n\\nThis enables networks to design privacy as a native feature rather than an external add-on.\\n\\n## Partnership models\\n\\nCurvy supports multiple collaboration models depending on ecosystem needs:\\n\\n- SDK-level integration\\n- network-level identity layer\\n- privacy infrastructure embedded into wallets\\n- ecosystem-wide privacy incentives\\n- strategic co-development\\n## Why integrate Curvy?\\n\\n- Enterprise-ready privacy infrastructure\\n- The best UX for private payments\\n- Non-custodial architecture\\n- Compliance-aware design  \\n- Automated transaction flows\\n- Programmable privacy flows  \\n- Multi-chain compatibility  \\n","rawMarkdownPath":"/_raw/for-businesses/for-networks.md","rawMarkdownTitle":"Curvy for networks","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-businesses/for-networks.md"},"headers":[],"relativePath":"for-businesses/for-networks.md","filePath":"for-businesses/for-networks.md","lastUpdated":1773768298000}'),o={name:"for-businesses/for-networks.md"};function i(s,e,l,u,c,d){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="curvy-for-networks" tabindex="-1">Curvy for networks <a class="header-anchor" href="#curvy-for-networks" aria-label="Permalink to &quot;Curvy for networks&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you are a blockchain ecosystem interested in partnering with Curvy, contact us at <strong><a href="mailto:hey@curvy.box" target="_blank" rel="noreferrer">hey@curvy.box</a></strong>.</p></div><p>Curvy provides native privacy infrastructure that can be integrated at the network level, enabling private, compliant, and programmable payment flows for your ecosystem participants.</p><p>In addition to default support for your network through the Curvy SDK and Curvy App, we offer deeper integration models tailored to your strategic goals.</p><h2 id="default-integration" tabindex="-1">Default Integration <a class="header-anchor" href="#default-integration" aria-label="Permalink to &quot;Default Integration&quot;">​</a></h2><p>Out of the box, Curvy supports:</p><ul><li>Private sending and receiving flows via the Curvy SDK</li><li>Network support within the Curvy App</li><li>Stealth address-based receiving</li><li>Privacy Aggregator support (where applicable)</li></ul><p>This allows your users, wallets, and applications to immediately benefit from privacy-enabled flows.</p><h2 id="custom-network-level-integrations" tabindex="-1">Custom Network-Level Integrations <a class="header-anchor" href="#custom-network-level-integrations" aria-label="Permalink to &quot;Custom Network-Level Integrations&quot;">​</a></h2><h3 id="white-label-user-domains" tabindex="-1">White-label user domains <a class="header-anchor" href="#white-label-user-domains" aria-label="Permalink to &quot;White-label user domains&quot;">​</a></h3><p>Launch your own ENS-style username namespace:</p><p><code>satoshi.yourdomain.io</code><br> instead of<br><code>satoshi.curvy.name</code></p><p>This allows your ecosystem to own the user-facing identity layer while leveraging Curvy’s underlying privacy infrastructure and customizing it to your needs.</p><h3 id="full-protocol-customization" tabindex="-1">Full protocol customization <a class="header-anchor" href="#full-protocol-customization" aria-label="Permalink to &quot;Full protocol customization&quot;">​</a></h3><p>For ecosystems seeking deeper integration, Curvy can be customized at the infrastructure level:</p><ul><li>control over transaction routing paths</li><li>selection of integrated DeFi protocols</li><li>definition of supported tokens</li><li>ecosystem-level fee configuration</li><li>subsidized privacy flows</li><li>incentive mechanisms for adoption</li></ul><p>This enables networks to design privacy as a native feature rather than an external add-on.</p><h2 id="partnership-models" tabindex="-1">Partnership models <a class="header-anchor" href="#partnership-models" aria-label="Permalink to &quot;Partnership models&quot;">​</a></h2><p>Curvy supports multiple collaboration models depending on ecosystem needs:</p><ul><li>SDK-level integration</li><li>network-level identity layer</li><li>privacy infrastructure embedded into wallets</li><li>ecosystem-wide privacy incentives</li><li>strategic co-development</li></ul><h2 id="why-integrate-curvy" tabindex="-1">Why integrate Curvy? <a class="header-anchor" href="#why-integrate-curvy" aria-label="Permalink to &quot;Why integrate Curvy?&quot;">​</a></h2><ul><li>Enterprise-ready privacy infrastructure</li><li>The best UX for private payments</li><li>Non-custodial architecture</li><li>Compliance-aware design</li><li>Automated transaction flows</li><li>Programmable privacy flows</li><li>Multi-chain compatibility</li></ul>',22)])])}const h=t(o,[["render",i]]);export{y as __pageData,h as default};
